function output = heartlib(M)
% output = heartlib(M)
%
%    ElementSets, BoundaryMatrices, UnsignedBoundaryMatrices, NonZeros, IndicatorVector  from MeshConnectivity
%    
%    M ∈ EdgeMesh 
%    
%    V, E = ElementSets( M )
%    `∂⁰` = BoundaryMatrices(M) 
%    `B⁰` = UnsignedBoundaryMatrices(M)
%    `B⁰ᵀ` = `B⁰`ᵀ
%    
%    Vertices(S) = S₁ where S: CellularSet
%    Edges(S)    = S₂ where S: CellularSet 
%     
%    Vertices(e) = vertexset(NonZeros(`B⁰` IndicatorVector({e}))) where e ∈ E
%    Vertices(H) = vertexset(NonZeros(`B⁰` IndicatorVector(H))) where H ⊂ E
%     
%    Edges(v) = edgeset(NonZeros(`B⁰ᵀ` IndicatorVector({v}))) where v ∈ V 
    dimv_0 = M.n_vertices();
    dime_0 = M.n_edges();
    dimf_0 = M.n_faces();
    [V, E] = M.ElementSets();
    % `∂⁰` = BoundaryMatrices(M)

    dee0 = M.BoundaryMatrices();
    % `B⁰` = UnsignedBoundaryMatrices(M)

    B0 = M.UnsignedBoundaryMatrices();
    % `B⁰ᵀ` = `B⁰`ᵀ

    B0T = B0';
    function [ret] = Vertices(S)
        ret = S(1);
    end

    function [ret_1] = Edges(S)
        ret_1 = S(2);
    end

    function [ret_2] = Vertices_0(e)
        assert(numel(e) == 1);
        assert( ismember(e, E) );

        ret_2 = NonZeros(B0 * indicator([e], M.n_edges()));
    end

    function [ret_3] = Vertices_1(H)
        ret_3 = NonZeros(B0 * indicator(H, M.n_edges()));
    end

    function [ret_4] = Edges_0(v)
        assert(numel(v) == 1);
        assert( ismember(v, V) );

        ret_4 = NonZeros(B0T * indicator([v], M.n_vertices()));
    end

    output.V = V;
    output.E = E;
    output.dee0 = dee0;
    output.B0 = B0;
    output.B0T = B0T;
    output.Vertices = @Vertices;
    output.Edges = @Edges;
    output.Vertices_0 = @Vertices_0;
    output.Vertices_1 = @Vertices_1;
    output.Edges_0 = @Edges_0;
    output.M = M;
end

